// Video and audio with FFmpeg: routes, command-line choices (no FFmpeg needed) and real conversions, which run only
// when Filee's FFmpeg is installed (`pwsh build/fetch-engines.ps1 -Only ffmpeg`; CI does not install it). Inputs are
// generated by FFmpeg itself (test pattern + sine tone) and every output is checked with ffprobe.

using System.Diagnostics;
using System.Globalization;
using System.Text.Json;
using Filee.Core.Conversion;
using Filee.Core.Formats;
using Filee.Core.Presets;
using Filee.Engines.Infrastructure;
using Filee.Engines.Media;

namespace Filee.Engines.Tests;

/// <summary>
/// FFmpeg keeps every core busy: its tests run on their own, so timing-sensitive tests of other classes (progress
/// estimates) are not starved meanwhile.
/// </summary>
[CollectionDefinition(nameof(FfmpegCollection), DisableParallelization = true)]
public sealed class FfmpegCollection;

[Collection(nameof(FfmpegCollection))]
public class MediaTests(EngineFixture fx) : IClassFixture<EngineFixture>
{
    [Fact]
    public void Cri_usm_game_videos_go_to_mp4_through_ffmpeg()
    {
        // #485: read only, through FFmpeg's usm demuxer; never a step towards something else.
        SkipUnlessInstalled();
        var route = fx.Catalog.CreatePlanner().Plan("usm", "mp4");
        Assert.NotNull(route);
        Assert.Equal("ffmpeg", Assert.Single(route.Steps).Converter.Id);
        Assert.Null(fx.Catalog.CreatePlanner().Plan("mp4", "usm"));
    }

    private static readonly (string Ffmpeg, string Ffprobe)? Tools = FfmpegConverter.Locate();

    private static void SkipUnlessInstalled() =>
        Assert.SkipUnless(Tools is not null, "FFmpeg is not installed (pwsh build/fetch-engines.ps1 -Only ffmpeg)");

    // ───────────────────────── Routes (no FFmpeg needed) ─────────────────────────

    /// <summary>A planner that treats FFmpeg as installed, so these tests also run where it is not.</summary>
    private RoutePlanner Planner() => fx.Catalog.CreatePlanner(["ffmpeg"]);

    [Theory]
    [InlineData("mp4", "webm")]
    [InlineData("mov", "mp4")]
    [InlineData("mkv", "mp4")]
    [InlineData("avi", "mp4")]
    [InlineData("mp4", "mp4")] // re-encode, e.g. the "MP4 720p" preset
    [InlineData("mp4", "gif")]
    [InlineData("mp4", "mp3")]
    [InlineData("webm", "m4a")]
    [InlineData("wav", "mp3")]
    [InlineData("flac", "mp3")]
    [InlineData("mp3", "mp3")] // re-encode, e.g. "MP3 128k"
    [InlineData("m4a", "wav")]
    [InlineData("amr", "mp3")]
    [InlineData("gif", "mp4")]
    [InlineData("gif", "webm")]
    [InlineData("png", "mov")]
    [InlineData("apng", "mp4")]
    [InlineData("mov", "apng")]
    [InlineData("rm", "mp4")]
    [InlineData("dss", "mp3")]
    [InlineData("mp4", "png")]
    [InlineData("ape", "flac")]
    [InlineData("wv", "mp3")]
    [InlineData("tta", "wv")]
    [InlineData("mpc", "m4a")]
    [InlineData("tak", "flac")]
    [InlineData("dsf", "wav")]
    [InlineData("dff", "flac")]
    [InlineData("dts", "eac3")]
    [InlineData("spx", "ogg")]
    [InlineData("wav", "w64")]
    [InlineData("mkv", "eac3")]
    public void Media_conversions_take_one_ffmpeg_step(string from, string to)
    {
        var route = Planner().Plan(from, to);
        Assert.NotNull(route);
        var step = Assert.Single(route.Steps);
        Assert.Equal("ffmpeg", step.Converter.Id);
    }

    [Theory]
    [InlineData("mp4", "jpg", "magick")]
    [InlineData("mkv", "webp", "magick")]
    [InlineData("mov", "pdf", "pdfsharp")]
    public void Video_to_images_goes_through_one_still_frame_not_an_animated_gif(string from, string to, string imageEngine)
    {
        var route = Planner().Plan(from, to);
        Assert.NotNull(route);
        Assert.Equal([("ffmpeg", from, "png"), (imageEngine, "png", to)], route.Steps.Select(s => (s.Converter.Id, s.From, s.To)));
        Assert.DoesNotContain(route.Steps, s => s.FrameSequence);
    }

    [Theory]
    [InlineData("mp4", "png")]
    [InlineData("mov", "jpg")]
    [InlineData("mkv", "jpg")]
    public void Every_frame_is_one_ffmpeg_step_only_when_asked_for(string from, string to)
    {
        var frames = Planner().Plan(from, to, frames: true);
        Assert.NotNull(frames);
        var step = Assert.Single(frames.Steps);
        Assert.Equal(("ffmpeg", from, to, true), (step.Converter.Id, step.From, step.To, step.FrameSequence));

        // Without it the same conversion is the still frame, as before.
        var still = Planner().Plan(from, to);
        Assert.NotNull(still);
        Assert.DoesNotContain(still.Steps, s => s.FrameSequence);
        Assert.Equal(("ffmpeg", from, "png"), (still.Steps[0].Converter.Id, still.Steps[0].From, still.Steps[0].To));
    }

    [Theory]
    [InlineData("mp4", "webp")] // frames are PNG or JPG only, never a step towards another format
    [InlineData("png", "jpg")] // not a video
    [InlineData("gif", "png")]
    public void Every_frame_has_no_route_but_its_own(string from, string to) =>
        Assert.Null(Planner().Plan(from, to, frames: true));

    [Theory]
    [InlineData("jpg", "wav")]
    [InlineData("png", "mp3")]
    [InlineData("gif", "flac")]
    public void A_picture_never_becomes_sound(string from, string to)
    {
        // Picture → video → audio would only make a silent file.
        Assert.Null(Planner().Plan(from, to));
        Assert.NotNull(Planner().Plan("mp4", to)); // a video still gives its sound
    }

    [Theory]
    [InlineData("jpg", "srt")]
    [InlineData("png", "vtt")]
    [InlineData("gif", "ass")]
    public void A_picture_never_becomes_subtitles(string from, string to)
    {
        // Picture → video → subtitles would only find none.
        Assert.Null(Planner().Plan(from, to));
        Assert.NotNull(Planner().Plan("mkv", to)); // a video still gives its subtitle track
    }

    [Fact]
    public void A_video_to_jpg_is_still_turned_by_the_image_engine()
    {
        // Rotate and flip presets on a video: the still frame is turned by ImageMagick, as before frames existed.
        var route = Planner().Plan("mp4", "jpg");
        Assert.NotNull(route);
        Assert.Equal(1, route.FirstTransformStep());
    }

    [Fact]
    public void Ordinary_routes_never_take_a_frame_step()
    {
        var planner = Planner();
        foreach (var from in FormatRegistry.Known.Where(f => f.Category == FormatCategory.Video).Select(f => f.Id))
        {
            foreach (var to in new[] { "jpg", "png", "webp", "pdf", "tiff", "gif", "mp4" })
            {
                if (planner.Plan(from, to) is { } route)
                    Assert.DoesNotContain(route.Steps, s => s.FrameSequence);
            }
        }
    }

    [Theory]
    [InlineData("heic", "mov", "magick")]
    [InlineData("jpg", "mp4", "magick")]
    [InlineData("avif", "webm", "magick")]
    [InlineData("svg", "mov", "vector")]
    [InlineData("qoi", "mp4", "magick")]
    public void Photos_reach_video_as_a_full_colour_png_not_a_gif(string from, string to, string imageEngine)
    {
        var route = Planner().Plan(from, to);
        Assert.NotNull(route);
        Assert.Equal([(imageEngine, from, "png"), ("ffmpeg", "png", to)], route.Steps.Select(s => (s.Converter.Id, s.From, s.To)));
    }

    [Theory]
    [InlineData("pdf", "mp4", "pdfium")] // a slideshow of the pages
    [InlineData("webp", "mov", "magick")] // an animated WebP keeps moving
    [InlineData("tiff", "webm", "magick")]
    [InlineData("mng", "mp4", "magick")]
    public void Animations_and_pages_still_reach_video_through_gif(string from, string to, string imageEngine)
    {
        var route = Planner().Plan(from, to);
        Assert.NotNull(route);
        Assert.Equal([(imageEngine, from, "gif"), ("ffmpeg", "gif", to)], route.Steps.Select(s => (s.Converter.Id, s.From, s.To)));
    }

    [Fact]
    public void Every_writable_video_and_audio_format_is_a_target()
    {
        // A new format in the catalog must get an encoding (or a documented reason why not) in MediaEncoding.
        Assert.Equal(
            FormatRegistry.Known.Where(f => f.Category == FormatCategory.Video && f.Writable).Select(f => f.Id).Order(),
            MediaEncoding.VideoTargets.Keys.Order());
        Assert.Equal(
            FormatRegistry.Known.Where(f => f.Category == FormatCategory.Audio && f.Writable).Select(f => f.Id).Order(),
            MediaEncoding.AudioTargets.Keys.Order());
    }

    [Fact]
    public void Audio_is_never_turned_into_video_and_ffmpeg_is_unavailable_until_installed()
    {
        var planner = Planner();
        Assert.Null(planner.Plan("mp3", "mp4"));
        Assert.Null(planner.Plan("wav", "gif"));

        var ffmpeg = fx.Converters.Single(c => c.Id == "ffmpeg");
        Assert.Equal(Tools is not null, ffmpeg.GetStatus().IsAvailable);
        if (Tools is null)
            Assert.Equal("engine.reason.not_installed", ffmpeg.GetStatus().ReasonKey);
    }

    // ───────────────────────── Command lines (no FFmpeg needed) ─────────────────────────

    private static readonly VideoStreamInfo Hd = new(1920, 1080, 1, 0, 29.97);

    private static IReadOnlyList<string> Args(string target, MediaOptions? options = null, MediaInfo? info = null) =>
        MediaEncoding.Plan("in.mkv", "out." + target, target, options ?? new MediaOptions(),
            info ?? new MediaInfo(TimeSpan.FromSeconds(10), Hd, new AudioStreamInfo(6, 44100), null), "work").Single().Arguments;

    private static string After(IReadOnlyList<string> args, string option) => args[args.ToList().IndexOf(option) + 1];

    [Fact]
    public void Quality_bitrate_and_size_options_reach_the_encoders()
    {
        var mp4 = Args("mp4", new MediaOptions { Quality = MediaQuality.High, MaxHeight = 720 });
        Assert.Equal("libx264", After(mp4, "-c:v"));
        Assert.Equal("18", After(mp4, "-crf"));
        Assert.Equal("scale=w=-2:h='trunc(min(ih,720)/2)*2'", After(mp4, "-vf"));
        Assert.Equal("+faststart", After(mp4, "-movflags"));
        Assert.Equal("768k", After(mp4, "-b:a")); // 256k per stereo pair × 3 pairs (5.1)
        Assert.Equal("mp4", After(mp4, "-f"));

        var webm = Args("webm", new MediaOptions { Quality = MediaQuality.Small, RemoveAudio = true });
        Assert.Equal(["-b:v", "0", "-crf", "38"], webm.SkipWhile(a => a != "-b:v").Take(4));
        Assert.Contains("-an", webm);
        Assert.DoesNotContain("0:a:0", webm);

        var mp3 = Args("mp3", new MediaOptions { AudioBitrateKbps = 130 });
        Assert.Equal("128k", After(mp3, "-b:a")); // snapped to the MP3 bitrate table
        Assert.DoesNotContain("-q:a", mp3);
        Assert.Equal("2", After(Args("mp3"), "-q:a")); // VBR V2 by default

        Assert.Equal("2", After(Args("wma"), "-ac")); // WMA holds two channels at most
        Assert.Equal("8000", After(Args("amr"), "-ar"));
        Assert.Equal("30000/1001", After(Args("mpg"), "-r"));
        Assert.Equal("448k", After(Args("vob"), "-b:a")); // DVD 5.1
    }

    [Fact]
    public void Channels_sample_rate_and_bit_depth_reach_the_audio_encoders()
    {
        // Low Opus bitrates for speech, mono (#37).
        var opus = Args("opus", new MediaOptions { AudioBitrateKbps = 32, AudioChannels = 1 });
        Assert.Equal("32k", After(opus, "-b:a"));
        Assert.Equal("1", After(opus, "-ac"));
        Assert.DoesNotContain("-ac", Args("opus"));

        var wav = Args("wav", new MediaOptions { AudioChannels = 1, AudioSampleRate = 16000, WavFormat = WavSampleFormat.Pcm24 });
        Assert.Equal("pcm_s24le", After(wav, "-c:a"));
        Assert.Equal("1", After(wav, "-ac"));
        Assert.Equal("16000", After(wav, "-ar"));
        Assert.Equal("pcm_s16le", After(Args("wav"), "-c:a")); // 16-bit stays the default
        Assert.DoesNotContain("-ar", Args("wav"));
        Assert.Equal("pcm_u8", After(Args("wav", new MediaOptions { WavFormat = WavSampleFormat.Pcm8 }), "-c:a"));
        Assert.Equal("pcm_f32le", After(Args("wav", new MediaOptions { WavFormat = WavSampleFormat.Float32 }), "-c:a"));

        // The sample rate is a WAV option only; AMR keeps its fixed mono 8 kHz.
        Assert.DoesNotContain("-ar", Args("flac", new MediaOptions { AudioSampleRate = 16000 }));
        var amr = Args("amr", new MediaOptions { AudioChannels = 2 });
        Assert.All(amr.Where((_, i) => i > 0 && amr[i - 1] == "-ac"), channels => Assert.Equal("1", channels));
    }

    [Fact]
    public void Streams_the_target_takes_as_they_are_are_copied()
    {
        var phone = new MediaInfo(TimeSpan.FromSeconds(10), new VideoStreamInfo(1920, 1080, 1, -90, 30, "hevc", "yuv420p10le"),
            new AudioStreamInfo(2, 44100, "aac"), null);
        var mp4 = Args("mp4", info: phone);
        Assert.Equal("copy", After(mp4, "-c:v"));
        Assert.Equal("hvc1", After(mp4, "-tag:v")); // Apple plays HEVC in MP4 only under this tag
        Assert.Equal("copy", After(mp4, "-c:a"));
        Assert.DoesNotContain("-vf", mp4);
        Assert.Equal("+faststart", After(mp4, "-movflags"));

        // WebM takes neither HEVC nor AAC.
        var webm = Args("webm", info: phone);
        Assert.Equal(("libvpx-vp9", "libopus"), (After(webm, "-c:v"), After(webm, "-c:a")));

        // Re-encoded: scaled down (the portrait video is 1920 high as shown), a small file asked for, a pixel format
        // players don't decode.
        Assert.Equal("libx264", After(Args("mp4", new MediaOptions { MaxHeight = 1080 }, phone), "-c:v"));
        Assert.Equal("copy", After(Args("mp4", new MediaOptions { MaxHeight = 2160 }, phone), "-c:v"));
        Assert.Equal("libx264", After(Args("mp4", new MediaOptions { Quality = MediaQuality.Small }, phone), "-c:v"));
        var yuv444 = phone with { Video = phone.Video! with { Codec = "h264", PixelFormat = "yuv444p" } };
        Assert.Equal("libx264", After(Args("mp4", info: yuv444), "-c:v"));

        // Audio alone is re-encoded when the container does not take it or the preset sets bitrate or channels.
        var pcm = phone with { Audio = new AudioStreamInfo(2, 48000, "pcm_s16le") };
        Assert.Equal(("copy", "aac"), (After(Args("mp4", info: pcm), "-c:v"), After(Args("mp4", info: pcm), "-c:a")));
        Assert.Equal("aac", After(Args("mov", new MediaOptions { AudioBitrateKbps = 128 }, phone), "-c:a"));
        Assert.Equal("aac", After(Args("mov", new MediaOptions { AudioChannels = 1 }, phone), "-c:a"));
        Assert.Equal("copy", After(Args("mov", new MediaOptions { AudioChannels = 2 }, phone), "-c:a"));
    }

    [Fact]
    public void Hevc_and_av1_presets_encode_with_x265_and_svt_av1()
    {
        var hevc = Args("mp4", new MediaOptions { VideoCodec = VideoCodec.Hevc });
        Assert.Equal(("libx265", "26", "yuv420p", "hvc1"), (After(hevc, "-c:v"), After(hevc, "-crf"), After(hevc, "-pix_fmt"), After(hevc, "-tag:v")));
        Assert.Equal("log-level=error", After(hevc, "-x265-params"));
        Assert.Equal("aac", After(hevc, "-c:a"));
        Assert.Equal(("22", "30"), (After(Args("mkv", new MediaOptions { VideoCodec = VideoCodec.Hevc, Quality = MediaQuality.High }), "-crf"),
            After(Args("mkv", new MediaOptions { VideoCodec = VideoCodec.Hevc, Quality = MediaQuality.Small }), "-crf")));
        Assert.DoesNotContain("-tag:v", Args("mkv", new MediaOptions { VideoCodec = VideoCodec.Hevc }));

        var av1 = Args("mp4", new MediaOptions { VideoCodec = VideoCodec.Av1 });
        Assert.Equal(("libsvtav1", "8", "32"), (After(av1, "-c:v"), After(av1, "-preset"), After(av1, "-crf")));
        var webm = Args("webm", new MediaOptions { VideoCodec = VideoCodec.Av1 });
        Assert.Equal(("libsvtav1", "libopus"), (After(webm, "-c:v"), After(webm, "-c:a")));

        // Targets that can't hold the codec keep their own: WebM has no HEVC, QuickTime no AV1, AVI neither.
        Assert.Equal("libvpx-vp9", After(Args("webm", new MediaOptions { VideoCodec = VideoCodec.Hevc }), "-c:v"));
        Assert.Equal("libx264", After(Args("mov", new MediaOptions { VideoCodec = VideoCodec.Av1 }), "-c:v"));
        Assert.Equal("mpeg4", After(Args("avi", new MediaOptions { VideoCodec = VideoCodec.Hevc }), "-c:v"));
    }

    [Fact]
    public void Av1_falls_back_to_libaom_and_a_missing_encoder_is_reported()
    {
        var info = new MediaInfo(TimeSpan.FromSeconds(10), Hd, new AudioStreamInfo(2, 48000), null);
        IReadOnlyList<string> Plan(VideoCodec codec, params string[] encoders) => MediaEncoding.Plan("in.mov", "out.mkv", "mkv",
            new MediaOptions { VideoCodec = codec }, info, "work", encoders: encoders.ToHashSet()).Single().Arguments;

        var aom = Plan(VideoCodec.Av1, "libaom-av1", "libx264", "aac");
        Assert.Equal(("libaom-av1", "0", "32", "6"), (After(aom, "-c:v"), After(aom, "-b:v"), After(aom, "-crf"), After(aom, "-cpu-used")));
        Assert.Contains("AV1 encoder", Assert.Throws<InvalidOperationException>(() => Plan(VideoCodec.Av1, "libx264")).Message);
        Assert.Contains("HEVC encoder", Assert.Throws<InvalidOperationException>(() => Plan(VideoCodec.Hevc, "libx264")).Message);
        // A video already in the codec needs no encoder at all.
        var hevcSource = info with { Video = Hd with { Codec = "hevc", PixelFormat = "yuv420p" } };
        Assert.Equal("copy", After(MediaEncoding.Plan("in.mov", "out.mkv", "mkv", new MediaOptions { VideoCodec = VideoCodec.Hevc }, hevcSource, "work",
            encoders: new HashSet<string>()).Single().Arguments, "-c:v"));
    }

    [Fact]
    public void Ten_bit_and_hdr_sources_stay_ten_bit_and_matching_codecs_are_copied()
    {
        var hlg = new VideoColor("bt2020", "arib-std-b67", "bt2020nc", "tv");
        var phone = new MediaInfo(TimeSpan.FromSeconds(10), new VideoStreamInfo(3840, 2160, 1, 0, 30, "hevc", "yuv420p10le", hlg),
            new AudioStreamInfo(2, 48000, "aac"), null);

        // HEVC asked for, HEVC given: rewrapped, 10-bit HDR untouched.
        Assert.Equal("copy", After(Args("mp4", new MediaOptions { VideoCodec = VideoCodec.Hevc }, phone), "-c:v"));
        // AV1 asked for: encoded in 10 bits with the HDR tags.
        var av1 = Args("mkv", new MediaOptions { VideoCodec = VideoCodec.Av1 }, phone);
        Assert.Equal(("libsvtav1", "yuv420p10le"), (After(av1, "-c:v"), After(av1, "-pix_fmt")));
        Assert.Equal(("bt2020", "arib-std-b67", "bt2020nc"), (After(av1, "-color_primaries"), After(av1, "-color_trc"), After(av1, "-colorspace")));
        // Scaled down: re-encoded, still 10 bits.
        var small = Args("mp4", new MediaOptions { VideoCodec = VideoCodec.Hevc, MaxHeight = 1080 }, phone);
        Assert.Equal(("libx265", "yuv420p10le"), (After(small, "-c:v"), After(small, "-pix_fmt")));

        // An H.264 source with HEVC asked for is encoded; an AV1 source with AV1 asked for goes into MP4 as it is.
        var h264 = phone with { Video = new VideoStreamInfo(1920, 1080, 1, 0, 30, "h264", "yuv420p") };
        var hevc = Args("mp4", new MediaOptions { VideoCodec = VideoCodec.Hevc }, h264);
        Assert.Equal(("libx265", "yuv420p"), (After(hevc, "-c:v"), After(hevc, "-pix_fmt")));
        Assert.DoesNotContain("-color_trc", hevc);
        var av1Source = phone with { Video = new VideoStreamInfo(1920, 1080, 1, 0, 30, "av1", "yuv420p") };
        Assert.Equal("copy", After(Args("mp4", new MediaOptions { VideoCodec = VideoCodec.Av1 }, av1Source), "-c:v"));
        Assert.Equal("libx264", After(Args("mp4", info: av1Source), "-c:v")); // H.264 stays the default for MP4

        Assert.True(new VideoStreamInfo(1, 1, 1, 0, 0, PixelFormat: "p010le").IsHighBitDepth);
        Assert.True(new VideoStreamInfo(1, 1, 1, 0, 0, PixelFormat: "yuv422p12le").IsHighBitDepth);
        Assert.False(new VideoStreamInfo(1, 1, 1, 0, 0, PixelFormat: "yuvj420p").IsHighBitDepth);
    }

    [Fact]
    public void Lossless_and_new_audio_targets_get_their_encoders()
    {
        var alac = Args("m4a", new MediaOptions { AudioCodec = AudioCodec.Alac, AudioBitrateKbps = 128 });
        Assert.Equal(("alac", "ipod"), (After(alac, "-c:a"), After(alac, "-f")));
        Assert.DoesNotContain("-b:a", alac);
        Assert.Equal("libmp3lame", After(Args("mp3", new MediaOptions { AudioCodec = AudioCodec.Alac }), "-c:a")); // ALAC is for M4A only
        Assert.Equal(("wavpack", "wv"), (After(Args("wv"), "-c:a"), After(Args("wv"), "-f")));
        Assert.Equal(("tta", "tta"), (After(Args("tta"), "-c:a"), After(Args("tta"), "-f")));
        var w64 = Args("w64", new MediaOptions { WavFormat = WavSampleFormat.Pcm24, AudioSampleRate = 48000 });
        Assert.Equal(("pcm_s24le", "48000", "w64"), (After(w64, "-c:a"), After(w64, "-ar"), After(w64, "-f")));
        Assert.Equal(("eac3", "576k"), (After(Args("eac3"), "-c:a"), After(Args("eac3"), "-b:a"))); // 192k per pair × 3 (5.1)

        // DSD (2.8 MHz) becomes 88.2 kHz PCM for lossless targets; lossy encoders choose their own rate.
        var dsd = new MediaInfo(TimeSpan.FromSeconds(10), null, new AudioStreamInfo(2, 2_822_400, "dsd_lsbf_planar"), null);
        Assert.Equal("88200", After(Args("flac", info: dsd), "-ar"));
        Assert.Equal("88200", After(Args("wav", info: dsd), "-ar"));
        Assert.Equal("16000", After(Args("wav", new MediaOptions { AudioSampleRate = 16000 }, dsd), "-ar"));
        Assert.Equal("44100", After(Args("ogg", info: dsd), "-ar"));
        Assert.DoesNotContain("-ar", Args("mp3", info: dsd));
    }

    [Fact]
    public void Dvd_and_dv_frames_are_letterboxed_into_the_nearest_tv_shape()
    {
        // 16:9 source: fills the anamorphic 16:9 NTSC frame.
        Assert.Equal("scale=720:480,pad=720:480:(ow-iw)/2:(oh-ih)/2:black,setdar=16/9", MediaEncoding.DvdOrDvFilter(Hd, pal: false));
        // 4:3 source at PAL.
        Assert.Equal("scale=720:576,pad=720:576:(ow-iw)/2:(oh-ih)/2:black,setdar=4/3",
            MediaEncoding.DvdOrDvFilter(new VideoStreamInfo(640, 480, 1, 0, 25), pal: true));
        // Cinemascope 2.39:1: 16:9 frame with bars above and below.
        Assert.Equal("scale=720:358,pad=720:480:(ow-iw)/2:(oh-ih)/2:black,setdar=16/9",
            MediaEncoding.DvdOrDvFilter(new VideoStreamInfo(1920, 804, 1, 0, 24), pal: false));
        // Portrait phone video (landscape pixels + 90° rotation): 4:3 frame with bars left and right.
        Assert.Equal("scale=304:480,pad=720:480:(ow-iw)/2:(oh-ih)/2:black,setdar=4/3",
            MediaEncoding.DvdOrDvFilter(new VideoStreamInfo(1920, 1080, 1, -90, 30), pal: false));

        Assert.True(MediaEncoding.IsPal(25));
        Assert.True(MediaEncoding.IsPal(50));
        Assert.False(MediaEncoding.IsPal(29.97));
        Assert.False(MediaEncoding.IsPal(0));
    }

    [Theory]
    [InlineData(29.97003, "30000/1001", "30000/1001")]
    [InlineData(25, "25", "25")]
    [InlineData(29.87, "30", "30000/1001")]
    [InlineData(15, "15", "24000/1001")]
    [InlineData(0, null, "25")]
